arguments.command:
cd /app && python3 -c "
seqs={}
n=None
for l in open('sequences.fasta'):
    l=l.strip()
    if l.startswith('>'): n=l[1:]; seqs[n]=''
    elif l: seqs[n]+=l
for k,v in seqs.items(): print(k, len(v))
import json; json.dump(seqs, open('/tmp/seqs.json','w'))
"

